];

int _rotr32(int x, int n) => ((x >> n) | (x << (32 - n))) & 0xFFFFFFFF;

/// Pure-Dart SHA-256 (FIPS 180-4). The script verifies downloads against
/// the pinned hashes before caching them — the same check that caught the
/// v1.0.697 corruption, but before the hook ever sees the file.
String sha256Hex(List<int> bytes) {
  final h = <int>[
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, //
    0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
  ];
  final bitLength = bytes.length * 8;
  final padded = <int>[...bytes, 0x80];
  while (padded.length % 64 != 56) {
    padded.add(0);
  }
  for (var i = 7; i >= 0; i--) {
    padded.add((bitLength >> (8 * i)) & 0xFF);
  }
  final w = List<int>.filled(64, 0);
  for (var chunk = 0; chunk < padded.length; chunk += 64) {
    for (var t = 0; t < 16; t++) {
      final b = chunk + 4 * t;
      w[t] =
          (padded[b] << 24) |
          (padded[b + 1] << 16) |
          (padded[b + 2] << 8) |
          padded[b + 3];
    }
    for (var t = 16; t < 64; t++) {
      final s0 =
          _rotr32(w[t - 15], 7) ^ _rotr32(w[t - 15], 18) ^ (w[t - 15] >> 3);
      final s1 =
          _rotr32(w[t - 2], 17) ^ _rotr32(w[t - 2], 19) ^ (w[t - 2] >> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) & 0xFFFFFFFF;
    }
    var a = h[0], b = h[1], c = h[2], d = h[3];
    var e = h[4], f = h[5], g = h[6], hh = h[7];
    for (var t = 0; t < 64; t++) {
      final s1 = _rotr32(e, 6) ^ _rotr32(e, 11) ^ _rotr32(e, 25);
      final ch = (e & f) ^ (~e & g);
      final temp1 = (hh + s1 + ch + _sha256K[t] + w[t]) & 0xFFFFFFFF;
      final s0 = _rotr32(a, 2) ^ _rotr32(a, 13) ^ _rotr32(a, 22);
      final maj = (a & b) ^ (a & c) ^ (b & c);
      final temp2 = (s0 + maj) & 0xFFFFFFFF;
      hh = g;
      g = f;
      f = e;
      e = (d + temp1) & 0xFFFFFFFF;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) & 0xFFFFFFFF;
    }
    h[0] = (h[0] + a) & 0xFFFFFFFF;
    h[1] = (h[1] + b) & 0xFFFFFFFF;
    h[2] = (h[2] + c) & 0xFFFFFFFF;
    h[3] = (h[3] + d) & 0xFFFFFFFF;
    h[4] = (h[4] + e) & 0xFFFFFFFF;
    h[5] = (h[5] + f) & 0xFFFFFFFF;
    h[6] = (h[6] + g) & 0xFFFFFFFF;
    h[7] = (h[7] + hh) & 0xFFFFFFFF;
  }
  return h.map((x) => x.toRadixString(16).padLeft(8, '0')).join();
}

// ── Pinned-asset parsing (the installed package is the single source of
// truth) ──

class PinnedAssets {
  final String? releaseTag;
  final Map<String, String> hashes;
  const PinnedAssets(this.releaseTag, this.hashes);
}

/// Parses the installed sqlite3 package's `lib/src/hook/asset_hashes.dart`
/// as text: the `releaseTag` constant and the filename → sha256 map. The
/// format is generated (`tool/write_asset_hashes.dart`) and stable across
/// 3.7.x–3.9.x; a structural change fails the parse loudly (and the guard
/// test's real-package probe fails first, named).
PinnedAssets parsePinnedAssets(String source) {
  final tagMatch = RegExp(
    r"const String\? releaseTag = '([^']+)'",
  ).firstMatch(source);
  final hashes = <String, String>{};
  final entryRe = RegExp("'([A-Za-z0-9_.]+)': '([0-9a-f]{64})'");
  for (final m in entryRe.allMatches(source)) {
    hashes[m.group(1)!] = m.group(2)!;
  }
  if (hashes.isEmpty) {
    throw const PrewarmException(
      'no pinned asset hashes found in asset_hashes.dart — the sqlite3 '
      'package changed its hook layout; update the parser and '
      'test/ci_sqlite3_prewarm_guard_test.dart TOGETHER',
    );
  }
  return PinnedAssets(tagMatch?.group(1), hashes);
}

// ── Target naming ──

/// Maps a target name (`<abi>-<os>`) to the release-asset file name the
/// sqlite3 hook downloads for it, where the extension follows the OS:
/// `.so` for linux/android, `.dylib` for apple targets, `.dll` for
/// windows. Naming quirk pinned to `asset_hashes.dart`: windows assets
/// have NO `lib` prefix (`sqlite3.x64.windows.dll`), every other OS uses
/// `libsqlite3.<abi>.<os>.<ext>`.
String sourceFilenameForTarget(String target) {
  final parts = target.split('-');
  if (parts.length != 2) {
    throw PrewarmException(
      'invalid target "$target" — expected <abi>-<os> (e.g. arm64-linux)',
    );
  }
  final abi = parts[0];
  final os = parts[1];
  const exts = {
    'linux': 'so',
    'android': 'so',
    'macos': 'dylib',
    'ios': 'dylib',
    'ios_sim': 'dylib',
    'windows': 'dll',
  };
  final ext = exts[os];
  if (ext == null) {
    throw PrewarmException(
      'invalid target "$target" — unknown OS "$os" (known: '
      '${exts.keys.join(', ')})',
    );
  }
  if (os == 'windows') {
    return 'sqlite3.$abi.$os.$ext';
  }
  return 'libsqlite3.$abi.$os.$ext';
}

/// The cache file name the hook writes for a target OS — the hook renames
/// downloads to `input.config.code.targetOS.libraryFileName('sqlite3',
/// DynamicLoadingBundled())`, NOT to the release-asset name (android and
/// linux both land as `libsqlite3.so`, in a `download-<hash8>` dir that is
/// unique per ABI).
String cachedFileNameForOs(String os) => switch (os) {
  'macos' || 'ios' || 'ios_sim' => 'libsqlite3.dylib',
  'windows' => 'sqlite3.dll',
  _ => 'libsqlite3.so',
};

/// Expands the `--targets` spec: `auto` → the host target, `android` →
/// the three APK ABIs (`flutter build apk` produces armeabi-v7a,
/// arm64-v8a, x86_64 — the x86/ia32 row is gone from Flutter's default
/// APK), explicit names pass through.
List<String> expandTargets(String spec, {required String hostTarget}) {
  final out = <String>[];
  for (final raw in spec.split(RegExp(r'[,\s]+'))) {
    final t = raw.trim();
    if (t.isEmpty) continue;
    switch (t) {
      case 'auto':
        out.add(hostTarget);
      case 'android':
        out.addAll(['arm-android', 'arm64-android', 'x64-android']);
      case 'ios':
        out.add('arm64-ios');
      default:
        out.add(t);
    }
  }
  if (out.isEmpty) {
    throw const PrewarmException('empty --targets spec');
  }
  return out;
}

/// The host's own `<abi>-<os>` target name (what `flutter test`/a host
/// `dart run` builds code assets for).
String hostTarget() {
  final os = Platform.operatingSystem;
  String abi;
  if (Platform.isWindows) {
    final arch = (Platform.environment['PROCESSOR_ARCHITECTURE'] ?? '')
        .toUpperCase();
    abi = switch (arch) {
      'ARM64' => 'arm64',
      'I386' || 'X86' => 'ia32',
      _ => 'x64',
    };
  } else {
    final result = Process.runSync('uname', ['-m']);
    if (result.exitCode != 0) {
      throw PrewarmException(
        'uname -m failed (exit ${result.exitCode}) — cannot resolve the '
        'host architecture for the auto target',
      );
    }
    final machine = '${result.stdout}'.trim();
    abi = switch (machine) {
      'x86_64' || 'amd64' => 'x64',
      'arm64' || 'aarch64' => 'arm64',
      'riscv64' => 'riscv64',
      _ => machine,
    };
  }
  final osName = switch (os) {
    'linux' => 'linux',
    'macos' => 'macos',
    'windows' => 'windows',
    'android' => 'android',
    _ => os,
  };
  return '$abi-$osName';
}

// ── Cache path (the hook's reuse location) ──

/// The exact file the sqlite3 hook's reuse path reads for a target:
/// `<root>/.dart_tool/hooks_runner/shared/sqlite3/build/download-<hash8>/`
/// `<cachedName>`, where hash8 is the first 8 hex chars of the PINNED hash
/// (`PrebuiltSqliteLibrary.dirname`) and cachedName is the hook's output
/// file name for that OS.
String cacheFilePathForTarget({
  required String packageRoot,
  required String target,
  required String pinnedSha256,
}) {
  final os = target.split('-').last;
  return '$packageRoot/.dart_tool/hooks_runner/shared/sqlite3/build/'
      'download-${pinnedSha256.substring(0, 8)}/${cachedFileNameForOs(os)}';
}

Uri sourceUri({
  required String urlPattern,
  required String? releaseTag,
  required String filename,
}) {
  if (releaseTag == null) {
    throw const PrewarmException(
      'asset_hashes.dart pins no releaseTag (a local/dev build of the '
      'sqlite3 package?) — cannot derive the download URL',
    );
  }
  final resolved = urlPattern
      .replaceAll(r'$RELEASE_TAG', releaseTag)
      .replaceAll(r'$FILENAME', filename);
  try {
    return Uri.parse(resolved);
  } on FormatException catch (e) {
    throw PrewarmException('invalid download URL "$resolved": ${e.message}');
  }
}

// ── The verified, bounded-retry download ──

class PrewarmException implements Exception {
  final String message;
  const PrewarmException(this.message);
  @override
  String toString() => message;
}

Future<File> downloadVerified({
  required Uri uri,
  required String expectedSha256,
  required File target,
  required int attempts,
  required int backoffBaseSeconds,
  required void Function(String line) log,
}) async {
  target.parent.createSync(recursive: true);
  final tmp = File('${target.path}.tmp');
  Object? lastError;
  for (var attempt = 1; attempt <= attempts; attempt++) {
    try {
      if (tmp.existsSync()) {
        tmp.deleteSync();
      }
      final client = HttpClient()
        // The hook itself resolves proxies from the environment
        // (sqlite3.dart #335); the prewarm must behave identically or it
        // breaks proxied runners the hook otherwise serves.
        ..findProxy = HttpClient.findProxyFromEnvironment;
      final request = await client.getUrl(uri);
      request.headers.add('User-Agent', 'fa sqlite3 native-assets prewarm');
      final response = await request.close();
      if (response.statusCode != HttpStatus.ok) {
        // Drain so the connection is not left dangling, then reject the
        // attempt explicitly — THIS is the check the sqlite3 hook lacks:
        // at v1.0.697 it piped a 504 error page straight into the output
        // file and only tripped on the hash afterwards.
        await response.drain<void>();
        throw PrewarmException('HTTP ${response.statusCode} for $uri');
      }
      final builder = BytesBuilder(copy: false);
      await for (final chunk in response) {
        builder.add(chunk);
      }
      final bytes = builder.takeBytes();
      final digest = sha256Hex(bytes);
      if (digest != expectedSha256) {
        throw PrewarmException(
          'sha256 mismatch for $uri: downloaded $digest, expected '
          '$expectedSha256',
        );
      }
      await tmp.writeAsBytes(bytes, flush: true);
      tmp.renameSync(target.path);
      client.close();
      return target;
    } on PrewarmException catch (e) {
      lastError = e;
      log('attempt $attempt/$attempts failed: ${e.message}');
    } catch (e) {
      lastError = e;
      log('attempt $attempt/$attempts failed: $e');
    }
    if (tmp.existsSync()) {
      try {
        tmp.deleteSync();
      } on FileSystemException {
        // A torn tmp is harmless — the next attempt recreates it.
      }
    }
    if (attempt < attempts) {
      final wait = backoffBaseSeconds * (1 << (attempt - 1));
      await Future<void>.delayed(Duration(seconds: wait));
    }
  }
  throw PrewarmException(
    'download failed after $attempts attempts: $lastError',
  );
}

// ── Per-package prewarm ──

class _TargetFailure {
  final String packageRoot;
  final String target;
  final Object error;
  const _TargetFailure(this.packageRoot, this.target, this.error);
}

/// Prewarms one package's hook cache. Returns the list of target names
/// that ended the run cached (or cleanly skipped). Throws [PrewarmException]
/// for structural problems (no package config, unparseable pins, unknown
/// explicit targets).
Future<List<String>> prewarmPackageRoot({
  required String packageRoot,
  required String targetSpec,
  required int attempts,
  required int backoffBaseSeconds,
  required String urlPattern,
  required void Function(String line) log,
}) async {
  final root = packageRoot.endsWith('/')
      ? packageRoot.substring(0, packageRoot.length - 1)
      : packageRoot;
  final configFile = File('$root/.dart_tool/package_config.json');
  if (!configFile.existsSync()) {
    throw PrewarmException(
      '$root/.dart_tool/package_config.json not found — run pub get '
      'before the prewarm (the prewarm reads the resolved sqlite3 '
      'location from the package config)',
    );
  }
  final config =
      jsonDecode(configFile.readAsStringSync()) as Map<String, Object?>;
  final packages = config['packages'] as List<Object?>;
  Map<String, Object?>? sqliteEntry;
  for (final pkg in packages) {
    final entry = pkg as Map<String, Object?>;
    if (entry['name'] == 'sqlite3') {
      sqliteEntry = entry;
      break;
    }
  }
  if (sqliteEntry == null) {
    log('$root: sqlite3 not in the package graph — no prewarm needed');
    return const [];
  }
  final rootUri = sqliteEntry['rootUri'] as String;
  final base = Directory('$root/.dart_tool').uri;
  var sqliteRoot = base.resolve(rootUri).toFilePath();
  if (sqliteRoot.endsWith('/')) {
    sqliteRoot = sqliteRoot.substring(0, sqliteRoot.length - 1);
  }
  final hashesFile = File('$sqliteRoot/lib/src/hook/asset_hashes.dart');
  if (!hashesFile.existsSync()) {
    throw PrewarmException(
      '${hashesFile.path} not found — the resolved sqlite3 package '
      '(${sqliteEntry['version'] ?? 'unknown version'}) predates the '
      'native-assets hook or moved its layout; update the parser and '
      'test/ci_sqlite3_prewarm_guard_test.dart TOGETHER',
    );
  }
  final pinned = parsePinnedAssets(hashesFile.readAsStringSync());
  log(
    '$root: sqlite3 ${sqliteEntry['version'] ?? ''} releaseTag '
    '${pinned.releaseTag} — prewarming targets: $targetSpec',
  );

  final host = hostTarget();
  final cached = <String>[];
  final failures = <_TargetFailure>[];
  for (final target in expandTargets(targetSpec, hostTarget: host)) {
    String filename;
    try {
      filename = sourceFilenameForTarget(target);
    } on PrewarmException catch (e) {
      failures.add(_TargetFailure(root, target, e));
      continue;
    }
    final pinnedHash = pinned.hashes[filename];
    if (pinnedHash == null) {
      final message =
          'no pinned prebuilt for target $target ($filename) in '
          '${pinned.releaseTag}';
      if (target == host) {
        // `auto` on a host whose pinned prebuilt the release does not
        // ship is a clean skip: there is nothing the hook would download
        // for that platform (every host CI uses today — linux, macos,
        // windows — HAS a pinned prebuilt; this is the guard for a
        // future platform gap).
        log(
          '$root: $message — skipping the auto target (the release '
          'ships no prebuilt for this host)',
        );
        continue;
      }
      failures.add(_TargetFailure(root, target, PrewarmException(message)));
      continue;
    }
    final cachePath = cacheFilePathForTarget(
      packageRoot: root,
      target: target,
      pinnedSha256: pinnedHash,
    );
    final cachedFile = File(cachePath);
    if (cachedFile.existsSync()) {
      final digest = sha256Hex(cachedFile.readAsBytesSync());
      if (digest == pinnedHash) {
        log(
          '$root: $target already cached (${cachePath.replaceFirst('$root/', '')})',
        );
        cached.add(target);
        continue;
      }
      log(
        '$root: $target cache entry is corrupted (sha256 $digest) — '
        'repairing',
      );
    }
    final uri = sourceUri(
      urlPattern: urlPattern,
      releaseTag: pinned.releaseTag,
      filename: filename,
    );
    try {
      await downloadVerified(
        uri: uri,
        expectedSha256: pinnedHash,
        target: cachedFile,
        attempts: attempts,
        backoffBaseSeconds: backoffBaseSeconds,
        log: (line) => log('$root: $target $line'),
      );
      log('$root: $target cached at download-${pinnedHash.substring(0, 8)}');
      cached.add(target);
    } on PrewarmException catch (e) {
      failures.add(_TargetFailure(root, target, e));
    }
  }
  if (failures.isNotEmpty) {
    for (final f in failures) {
      log('${f.packageRoot}: FAILED ${f.target}: ${f.error}');
    }
    throw PrewarmException(
      '${failures.length} of ${cached.length + failures.length} targets '
      'failed for $root (first: ${failures.first.target}: '
      '${failures.first.error})',
    );
  }
  return cached;
}

// ── CLI ──

Future<int> runMain(List<String> args) async {
  var packageRoots = <String>[];
  var targetSpec = 'auto';
  var attempts = 4;
  var backoffBaseSeconds = 5;
  var urlPattern =
      r'https://github.com/simolus3/sqlite3.dart/releases/download/$RELEASE_TAG/$FILENAME';
  var quiet = false;
  for (var i = 0; i < args.length; i++) {
    final a = args[i];
    switch (a) {
      case '--package-root':
        packageRoots.add(args[++i]);
      case '--targets':
        targetSpec = args[++i];
      case '--attempts':
        attempts = int.parse(args[++i]);
      case '--backoff-base-seconds':
        backoffBaseSeconds = int.parse(args[++i]);
      case '--url-pattern':
        urlPattern = args[++i];
      case '--quiet':
        quiet = true;
      default:
        stderr.writeln('unknown argument: $a');
        stderr.write(_usage);
        return 2;
    }
  }
  if (packageRoots.isEmpty) {
    packageRoots = ['.'];
  }
  void log(String line) {
    if (!quiet) {
      stdout.writeln(line);
    }
  }

  final failures = <_TargetFailure>[];
  for (final root in packageRoots) {
    try {
      await prewarmPackageRoot(
        packageRoot: root,
        targetSpec: targetSpec,
        attempts: attempts,
        backoffBaseSeconds: backoffBaseSeconds,
        urlPattern: urlPattern,
        log: log,
      );
    } on PrewarmException catch (e) {
      failures.add(_TargetFailure(root, targetSpec, e));
    }
  }
  if (failures.isNotEmpty) {
    for (final f in failures) {
      stderr.writeln('PREWARM FAILED — ${f.packageRoot}: ${f.error}');
    }
    stderr.writeln(
      'gh-2072 context: the sqlite3 hook downloads prebuilt binaries at '
      'build time in a single unchecked attempt; this prewarm exists so a '
      'transient GitHub error (504 Gateway Time-out error page saved as '
      'the library, rejected by the hook hash check) cannot red the leg. '
      'If the failure persists, check the runner egress to '
      'github.com/simolus3/sqlite3.dart releases.',
    );
    return 1;
  }
  return 0;
}

const _usage =
    'usage: dart run scripts/sqlite3_native_assets_prewarm.dart '
    '[--package-root <dir>]... [--targets auto|android|arm64-ios|<abi>-<os>] '
    '[--attempts <n>] [--backoff-base-seconds <s>] [--url-pattern <p>] '
    '[--quiet]\n';

Future<void> main(List<String> args) async {
  exitCode = await runMain(args);
}

// gh-2072 — the v1.0.697 tag run red'd four CI legs + the aggregate
// Quality gate on ONE shared flake: the `sqlite3` package's native-assets
// build hook downloads its prebuilt binaries from GitHub releases at
// build time in a single attempt with no HTTP status check, so one
// transient `504 Gateway Time-out` error page (saved as the library file,
// then rejected by the hook's own sha256 check) kills every leg that
// compiles the root package (`dart test`/`dart run`/`dart build`) or
// flutter_app (`flutter test`/`flutter build`). The identical tree was
// green on the SM validation run hours earlier — pure network roulette
// the release train rides on every tag.
//
// The cure follows the gh-1655/gh-1757 pre-install pattern (bounded-retry
// pre-fetch into the exact path the unretryable consumer reads, guard
// test pins the wiring). This guard is deliberately YAML-level (the
// static-pattern style of test/ci_android_ndk_preinstall_guard_test.dart
// — a future leg must red HERE, not silently re-enter the download
// roulette):
//   AC1  the shared composite action exists, is composite, and delegates
//        to the prewarm script (no second URL pin in the action),
//   AC2  the prewarm script carries the whole safety contract: bounded
//        retry, HTTP status check, sha256 verification, atomic tmp→rename,
//        idempotent hash-checked reuse, the hook's download-<hash8> cache
//        convention, and the pinned asset_hashes.dart parsing,
//   AC3  every workflow job that builds the root package or compiles the
//        app carries the prewarm BEFORE its first hook-building step —
//        the enumerated map below is the contract (a count below means a
//        job lost the prewarm in a refactor; above means a new
//        hook-building site appeared that the map must acknowledge),
//   AC4  the shared flutter-pub-get action ends with the central prewarm,
//        so every flutter leg is covered by one edit,
//   AC5  the target routing for cross-target legs is explicit: the
//        android legs request the APK ABI triple, the iOS legs request
//        arm64-ios, and nightly's release matrix routes per row (web
//        builds no code assets and is excluded).
import 'dart:io';

import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

String read(String path) => File(path).readAsStringSync();

const prewarmAction = './.github/actions/sqlite3-native-assets-prewarm';
const actionPath = '.github/actions/sqlite3-native-assets-prewarm/action.yml';
const scriptPath = 'scripts/sqlite3_native_assets_prewarm.dart';
const pubGetActionPath = '.github/actions/flutter-pub-get/action.yml';

/// Every (workflow, jobs) pair whose jobs build the root package's
/// native-assets hook (`dart test`/`dart run`/`dart compile`/`dart build`
/// on a package graph carrying sqlite3 via flutter_agent_memory) or
/// compile flutter_app (flutter test / apk / appbundle / ios / macos /
/// linux / windows builds, fastlane release lanes). The same class
/// enumeration the gh-1655 guard pins: the network-roulette fix must
/// cover the whole release-blocking class, not just the four legs that
/// happened to lose the dice at v1.0.697.
///
/// ci.yml build-macos and build-web are intentionally absent: build-macos
/// needs only the host-macos target, which the central flutter-pub-get
/// prewarm (AC4) provides, and build-web compiles no code assets.
const sqlite3PrewarmJobs = <String, List<String>>{
  '.github/workflows/ci.yml': [
    'test-core',
    'static',
    'cube-kernel-live',
    'integration-mock',
    'installer-portability',
    'hostile-env',
    'fa-aot-build',
    'pty-integration-linux',
    'pty-visual',
    'guards',
    'model-switch-reg',
    'cli-visual-settings',
    'dep-audit',
    'perf-gate',
    'usage-fold',
    'integration',
    'js-ext-integration',
    'build-android',
    'build-ios',
  ],
  '.github/workflows/build-mobile.yml': [
    'build-android',
    'build-android-apks',
    'test-android-emulator',
    'build-ios',
  ],
  '.github/workflows/nightly.yml': ['build-release', 'pty-integration'],
  '.github/workflows/browser-ext.yml': ['headless-suite'],
  '.github/workflows/coverage-gardener.yml': ['measure-and-file'],
};

/// Run-step signatures that mean "this step builds the root package's
/// native-assets hook or compiles the app" — the prewarm must run before
/// any of them in the same job. `matrix.cmd` covers nightly's build-release
/// matrix, where the per-row command is interpolated at job level.
/// Deliberately NOT a signature: `dart pub get` (pub get never builds
/// hooks) and the firebase_options.dart template sanity-compiles (their
/// import graph reaches no code asset).
final hookBuildingSignatures = [
  RegExp(r'\bdart (?:test|run|compile|build)\b'),
  RegExp(r'\bdart bin/\S+\.dart\b'),
  RegExp(r'\bflutter test\b'),
  RegExp(r'\bflutter build (?:apk|appbundle|ios|ipa|macos|linux|windows)\b'),
  RegExp(r'fastlane android build_release\b'),
  RegExp(r'matrix\.cmd'),
];

/// Jobs that compile the app for a NON-host target: the central host-auto
/// prewarm cannot cover them, so the map entries must pass explicit
/// targets. The APK ABI triple is what `flutter build apk` produces by
/// default (armeabi-v7a, arm64-v8a, x86_64 — no x86/ia32 row since
/// Flutter 3.22); iOS device builds are arm64.
const explicitTargetJobs = <String, String>{
  'ci.yml/build-android': 'android',
  'build-mobile.yml/build-android': 'android',
  'build-mobile.yml/build-android-apks': 'android',
  'build-mobile.yml/test-android-emulator': 'android',
  'ci.yml/build-ios': 'arm64-ios',
  'build-mobile.yml/build-ios': 'arm64-ios',
};

YamlMap workflowRoot(String workflowPath) =>
    loadYaml(read(workflowPath)) as YamlMap;

YamlList jobSteps(String workflowPath, String jobKey) {
  final jobs = workflowRoot(workflowPath)['jobs'] as YamlMap;
  final job = jobs[jobKey] as YamlMap;
  return job['steps'] as YamlList;
}

List<int> prewarmIndexes(YamlList steps) => [
  for (var i = 0; i < steps.length; i++)
    if ((steps[i] as YamlMap)['uses'] == prewarmAction) i,
];

List<int> signatureIndexes(YamlList steps) => [
  for (var i = 0; i < steps.length; i++)
    if (hookBuildingSignatures.any(
      (re) => re.hasMatch('${(steps[i] as YamlMap)['run'] ?? ''}'),
    ))
      i,
];

void main() {
  group('gh-2072 — sqlite3 native-assets prewarm wiring', () {
    test('AC1: the composite action exists and delegates to the script', () {
      final action = loadYaml(read(actionPath)) as YamlMap;
      expect(action['name'], isNotNull);
      final runs = action['runs'] as YamlMap;
      expect(runs['using'], 'composite');
      final steps = runs['steps'] as YamlList;
      expect(steps, isNotEmpty);
      final body = read(actionPath);
      expect(
        body,
        contains('sqlite3_native_assets_prewarm.dart'),
        reason:
            'the action must invoke the shared prewarm script — a second '
            'implementation in YAML would drift from the tested contract',
      );
      expect(
        body,
        isNot(contains('releases/download')),
        reason:
            'the release URL pattern must live ONLY in the script (and the '
            'sqlite3 package itself) — a second URL pin in the action '
            'drifts from the hook the cached files must satisfy',
      );
    });

    test('AC2: the script carries the full safety contract', () {
      final body = read(scriptPath);
      expect(
        body,
        contains('asset_hashes.dart'),
        reason:
            'the pinned hashes must be parsed from the installed sqlite3 '
            'package itself — a second pin drifts the moment the '
            'lockfile/float moves the version',
      );
      expect(
        body,
        contains('releaseTag'),
        reason:
            'the download URL needs the release tag from the same '
            'pinned source',
      );
      expect(
        body,
        contains('download-'),
        reason:
            "the cache path must reuse the hook's "
            'download-<hash8> convention so the hook finds and reuses the '
            'prewarmed file instead of fetching',
      );
      expect(
        body,
        contains('statusCode'),
        reason:
            'gh-2072: the hook died because it piped a 504 error page into '
            'the output file with no status check — the prewarm must '
            'reject non-200 responses explicitly',
      );
      expect(
        body,
        contains('sha256'),
        reason:
            'the prewarm must verify the downloaded bytes against the '
            'pinned hash before caching — the same check that caught the '
            'v1.0.697 corruption, but before the hook ever sees the file',
      );
      expect(
        body,
        contains('.tmp'),
        reason:
            'downloads must land atomically (tmp then rename) — a torn '
            'download must never be visible at the cache path the hook '
            'reads',
      );
      expect(
        body,
        contains('for (var attempt'),
        reason:
            'the fetch must be bounded-retried — the whole point of the '
            'prewarm is that one transient 504 is not fatal (gh-2072)',
      );
      expect(
        body,
        contains('findProxyFromEnvironment'),
        reason:
            'the hook itself respects proxy environment variables; the '
            'prewarm must too or it breaks proxied runners',
      );
    });

    for (final entry in sqlite3PrewarmJobs.entries) {
      final workflow = entry.key;
      for (final jobKey in entry.value) {
        test('AC3: $workflow $jobKey prewarms before its first '
            'hook-building step', () {
          final steps = jobSteps(workflow, jobKey);
          final signatures = signatureIndexes(steps);
          expect(
            signatures,
            isNotEmpty,
            reason:
                'precondition: $workflow $jobKey must contain a '
                'hook-building step (dart test/run/compile/build, flutter '
                'test/build, fastlane release, or matrix.cmd) — otherwise '
                'this map entry pins nothing and should be removed',
          );
          final prewarm = prewarmIndexes(steps);
          expect(
            prewarm,
            isNotEmpty,
            reason:
                '$workflow $jobKey builds the root package\'s native-assets '
                'hook (or compiles the app) without prewarming the sqlite3 '
                'prebuilt binaries — the hook then downloads them from '
                'GitHub releases in a single attempt with no status check, '
                'and one transient 504 error page reds the leg and the '
                'aggregate Quality gate (gh-2072). Add `uses: '
                '$prewarmAction` before the first hook-building step.',
          );
          for (final prewarmIndex in prewarm) {
            for (final signatureIndex in signatures) {
              expect(
                prewarmIndex,
                lessThan(signatureIndex),
                reason:
                    '$workflow $jobKey runs the sqlite3 prewarm AFTER a '
                    'hook-building step — the hook builds during that '
                    'step, so a later prewarm never applies',
              );
            }
          }
        });

        final explicitKey = '${workflow.split('/').last}/$jobKey';
        final expectedTargets = explicitTargetJobs[explicitKey];
        if (expectedTargets != null) {
          test('AC5: $workflow $jobKey requests explicit targets '
              '($expectedTargets)', () {
            final steps = jobSteps(workflow, jobKey);
            final targets = [
              for (final step in steps.whereType<YamlMap>())
                if (step['uses'] == prewarmAction && step['with'] is YamlMap)
                  '${(step['with'] as YamlMap)['targets'] ?? ''}',
            ];
            expect(
              targets,
              isNotEmpty,
              reason:
                  '$explicitKey compiles for a non-host target — the '
                  'host-auto prewarm cannot provision those binaries. Pass '
                  "targets: $expectedTargets to the prewarm action",
            );
            expect(
              targets.any((t) => t.contains(expectedTargets)),
              isTrue,
              reason:
                  '$explicitKey must request targets: $expectedTargets — '
                  'the host-auto default provisions only the runner\'s own '
                  'platform, not the APK ABIs / iOS device binaries the '
                  'hook will ask for',
            );
          });
        }
      }

      test('AC3: $workflow references the prewarm action exactly '
          '(${entry.value.length} job(s))', () {
        final jobs = workflowRoot(workflow)['jobs'] as YamlMap;
        final usesCount = jobs.values
            .whereType<YamlMap>()
            .map((job) => job['steps'])
            .whereType<YamlList>()
            .expand((steps) => steps)
            .whereType<YamlMap>()
            .where((step) => step['uses'] == prewarmAction)
            .length;
        expect(
          usesCount,
          entry.value.length,
          reason:
              '$workflow must prewarm through `$prewarmAction` exactly '
              '${entry.value.length} time(s) — a count BELOW means a build '
              'job lost the prewarm in a refactor; ABOVE means a new site '
              'appeared that the sqlite3PrewarmJobs map must acknowledge '
              '(either way the guard, not the roulette, decides)',
        );
      });
    }

    test('AC4: the shared flutter-pub-get action ends with the central '
        'prewarm', () {
      final steps =
          (loadYaml(read(pubGetActionPath)) as YamlMap)['runs'] as YamlMap;
      final list = steps['steps'] as YamlList;
      final last = list.last as YamlMap;
      expect(
        '${last['run'] ?? ''}',
        contains('sqlite3_native_assets_prewarm.dart'),
        reason:
            'every flutter leg resolves flutter_app through '
            'flutter-pub-get (test/ci_pub_get_retry_guard_test.dart '
            'enforces that) — the central prewarm at the end of the action '
            'is what covers the flutter legs (flutter-tests, pty legs, '
            'build-macos, exzone, …) without per-job edits',
      );
    });
  });
}

